// Do not edit this file as it will be overwritten if HAMR codegen is rerun

//! Copies of the component GUMBO contracts for system-level verification.
//! The originals live in the component crates, which this crate cannot
//! depend on (they are staticlibs); both are generated from the same
//! GUMBO source, so they are identical by construction (TCB item T3).

#![allow(non_snake_case)]

use data::*;
use vstd::prelude::*;

verus! {

// -- 'above_top.Impl'_Instance.A_sub.a --
pub mod outer_a {
  use super::*;

  /** initialize guarantee A_Initial_Input_Range
    *   A input is initially in the system range
    */
  pub open spec fn initialize_A_Initial_Input_Range(
    api_Input: i32) -> bool
  {
    api_Input < 10i32
  }

  /** compute assume A_Input_Range
    *   A input range
    */
  pub open spec fn compute_spec_A_Input_Range_assume(
    api_Input: i32) -> bool
  {
    api_Input < 50i32
  }

  /** compute guarantee A_Output_Range
    *   A output range
    */
  pub open spec fn compute_spec_A_Output_Range_guarantee(
    api_Input: i32,
    api_Output: i32) -> bool
  {
    api_Output < 2i32 * api_Input
  }
}

// -- 'above_top.Impl'_Instance.top_sub.A_sub.a --
pub mod a {
  use super::*;

  /** initialize guarantee A_Initial_Input_Range
    *   A input is initially in the system range
    */
  pub open spec fn initialize_A_Initial_Input_Range(
    api_Input: i32) -> bool
  {
    api_Input < 10i32
  }

  /** compute assume A_Input_Range
    *   A input range
    */
  pub open spec fn compute_spec_A_Input_Range_assume(
    api_Input: i32) -> bool
  {
    api_Input < 50i32
  }

  /** compute guarantee A_Output_Range
    *   A output range
    */
  pub open spec fn compute_spec_A_Output_Range_guarantee(
    api_Input: i32,
    api_Output: i32) -> bool
  {
    api_Output < 2i32 * api_Input
  }
}

// -- 'above_top.Impl'_Instance.top_sub.B_sub.b --
pub mod b {
  use super::*;

  /** compute assume B_Input_Range
    *   B input range
    */
  pub open spec fn compute_spec_B_Input_Range_assume(
    api_Input: i32) -> bool
  {
    api_Input < 50i32
  }

  /** compute guarantee B_Output_Range
    *   B output range
    */
  pub open spec fn compute_spec_B_Output_Range_guarantee(
    api_Input: i32,
    api_Output: i32) -> bool
  {
    api_Output < api_Input + 15i32
  }
}

// -- 'above_top.Impl'_Instance.top_sub.C_sub.c --
pub mod c {
  use super::*;

  /** compute guarantee C_Output_Range
    *   C output range
    */
  pub open spec fn compute_spec_C_Output_Range_guarantee(
    api_Input1: i32,
    api_Input2: i32,
    api_Output: i32) -> bool
  {
    api_Output == api_Input1 + api_Input2
  }
}

} // verus!
